// Build-time catalog access. Data is generated by scripts/build-catalog.mjs.
import catalogData from '@/content/generated/catalog.json';
import { getImage, hasImage } from './images';
import type { Category, ClientProduct, Crumb, ImageRef, Product } from './types';

interface CatalogFile {
  applicationVocabulary: string[];
  retiredLegacyPages: { slug: string; redirectTo: string; reason: string }[];
  categories: Category[];
  products: Product[];
}

const catalog = catalogData as unknown as CatalogFile;
const bySlug = new Map(catalog.categories.map((c) => [c.slug, c]));

export const allCategories = (): Category[] => catalog.categories;
export const allProducts = (): Product[] => catalog.products;
export const retiredLegacyPages = () => catalog.retiredLegacyPages;
export const applicationVocabulary = () => catalog.applicationVocabulary;

export const topLevelCategories = () => catalog.categories.filter((c) => !c.parent);
export const getCategory = (slug: string) => bySlug.get(slug);
export const childCategories = (slug: string) =>
  (bySlug.get(slug)?.children ?? []).map((s) => bySlug.get(s)).filter((c): c is Category => Boolean(c));

export function requireCategory(slug: string): Category {
  const c = bySlug.get(slug);
  if (!c) throw new Error(`Unknown category ${slug}`);
  return c;
}

/** The category itself plus every descendant slug. */
export function scopeOf(slug: string): Set<string> {
  const out = new Set<string>([slug]);
  for (const child of childCategories(slug)) for (const s of scopeOf(child.slug)) out.add(s);
  return out;
}

export function productsIn(slug: string): Product[] {
  const scope = scopeOf(slug);
  return catalog.products.filter((p) => scope.has(p.collection));
}

export function ancestors(slug: string): Category[] {
  const chain: Category[] = [];
  let c = bySlug.get(slug);
  while (c) {
    chain.unshift(c);
    c = c.parent ? bySlug.get(c.parent) : undefined;
  }
  return chain;
}

export function categoryCrumbs(slug: string): Crumb[] {
  return [
    { name: 'Home', href: '/' },
    { name: 'Products', href: '/products' },
    ...ancestors(slug).map((c) => ({ name: c.name, href: `/${c.slug}` })),
  ];
}

export const categoryHref = (slug: string) => `/${slug}`;

export function imageOrNull(key: string | null): ImageRef | null {
  return key && hasImage(key) ? getImage(key) : null;
}

export function toClientProduct(p: Product): ClientProduct {
  return {
    id: p.id,
    name: p.name,
    category: p.category,
    subcategory: p.subcategory,
    collection: p.collection,
    img: imageOrNull(p.image),
    colours: p.colours,
    finish: p.finish,
    applications: p.applications,
    origin: p.origin,
    size: p.size,
    tags: p.tags,
  };
}

/** slug -> display name, for every category (used for card meta and filter labels). */
export const categoryNames = (): Record<string, string> =>
  Object.fromEntries(catalog.categories.map((c) => [c.slug, c.name]));

export const categoryOrder = (): string[] => catalog.categories.map((c) => c.slug);
